// Calcola la distanza dal centro esatto della figura
float dist = pModel.y;

// 'fract' taglia il numero decimale creando strisce nette (effetto anello)
// Sottraendo ubuf.u_time gli anelli si espandono verso l'esterno
float anelli = fract(dist * 10.0 - ubuf.u_time * 2.0); 

// Rende i bordi degli anelli leggermente sfumati
anelli = smoothstep(0.0, 0.2, anelli) * smoothstep(1.0, 0.8, anelli);

vec3 colFondo = vec3(0.05, 0.05, 0.1); // Blu notte
vec3 colRadar = vec3(0.2, 1.0, 0.4);   // Verde radar

textureCol = mix(colFondo, colRadar, anelli);
